const PAGE: PageRequest = { limit: 20, offset: 0 };
/** TODAY plus the 28-day catalog window. */
const WINDOW_END = '2026-11-12';
const OLD_PHOTO: ImageRef = {
  id: 'a0000000-0000-4000-8000-000000000011',
  width: 2560,
  height: 1707,
  crop: { left: 0, top: 213, width: 2560, height: 1280 },
};
const PHOTO: ImageRef = { ...OLD_PHOTO, id: 'a0000000-0000-4000-8000-000000000012' };
const LOGO: ImageRef = { id: 'a0000000-0000-4000-8000-000000000013', width: 512, height: 512, crop: null };
/** anEvent()'s organizer as the API returns it. */
const ORGANIZER = { id: ACCOUNT_ID, name: 'Natalka Park', logo: null };
const UPLOAD = {
  content: new Uint8Array([1, 2, 3]),
  contentType: 'image/jpeg',
  crop: { left: 0, top: 0.1, width: 1, height: 0.75 },
};

/** Every dependency of EventsService as a mock; a test changes only what it needs. */
function makeService() {
  const eventsRepository = {
    findById: mock.fn((): Promise<Event | undefined> => Promise.resolve(anEvent())),
    findByOrganization: mock.fn(
      (_organizationId: string, _endingAfter: Date, page: PageRequest): Promise<Page<Event>> =>
        Promise.resolve({ items: [anEvent()], page: { ...page, hasMore: false } }),
    ),
    findPublished: mock.fn((_filter: EventFilter, page: PageRequest): Promise<Page<Event>> =>
      Promise.resolve({ items: [anEvent()], page: { ...page, hasMore: false } }),
    ),
    create: mock.fn((record: EventRecord): Promise<Event> => Promise.resolve(anEvent({ ...record }))),
    update: mock.fn((id: string, changes: EventChanges) => Promise.resolve({ ...anEvent({ id }), ...changes })),
    setPhoto: mock.fn((id: string, photoId: string | null) => Promise.resolve(anEvent({ id, photoId }))),
  };
  const organizationsRepository = {
    findByAccountId: mock.fn((): Promise<Organization | undefined> => Promise.resolve(anOrganization())),
  };
  const venuesRepository = { findById: mock.fn((): Promise<Venue | undefined> => Promise.resolve(aVenue())) };
  const categoriesService = {
    findActive: mock.fn((): Promise<Category | undefined> => Promise.resolve(aCategory())),
  };

  const { imagesService } = fakeImages([OLD_PHOTO, PHOTO, LOGO], PHOTO);
  const transactions = aTransactionRunner();
  const jobs = aJobQueue();

  const service = new EventsService(
    eventsRepository as unknown as EventsRepository,
    organizationsRepository as unknown as OrganizationsRepository,
    venuesRepository as unknown as VenuesRepository,
    categoriesService as unknown as CategoriesService,
    imagesService as unknown as ImagesService,
    transactions,
    jobs as unknown as JobQueue,
  );
  return {
    service,
    eventsRepository,
    organizationsRepository,
    venuesRepository,
    categoriesService,
    imagesService,
    jobs,
    tx: TX,
  };
}

function isDomainError(code: string) {
  return (error: unknown) => error instanceof DomainError && error.code === code;
}

// FR-006, FR-007; catalog access, rule 2: only the coming 28 days.
describe('EventsService.list', () => {
  useFixedClock();

  const windowCases = [
    { title: 'covers today to the end of the window without dates', query: {}, from: TODAY, to: WINDOW_END },
    {
      title: 'moves a start in the past to today',
      query: { from: '2026-10-01', to: '2026-10-20' },
      from: TODAY,
      to: '2026-10-20',
    },
    {
      title: 'moves an end beyond the window to its end',
      query: { from: '2026-10-20', to: '2026-12-31' },
      from: '2026-10-20',
      to: WINDOW_END,
    },
    {
      title: 'keeps dates inside the window',
      query: { from: '2026-10-20', to: '2026-10-25' },
      from: '2026-10-20',
      to: '2026-10-25',
    },
  ];

  for (const { title, query, from, to } of windowCases) {
    test(title, async () => {
      const { service, eventsRepository } = makeService();

      await service.list(query, PAGE);

      assert.deepEqual(eventsRepository.findPublished.mock.calls[0]?.arguments, [{ ...query, from, to }, PAGE]);
    });
  }

  // Regression for #206: the end date was compared the wrong way round, so a client could read past the window.
  const windowEndCases = [
    { title: 'keeps the last day of the window', to: WINDOW_END, expected: WINDOW_END },
    { title: 'keeps the day before the last day of the window', to: '2026-11-11', expected: '2026-11-11' },
    { title: 'moves the day after the window to its last day', to: '2026-11-13', expected: WINDOW_END },
    { title: 'moves a date a year ahead to the last day of the window', to: '2027-10-15', expected: WINDOW_END },
  ];

  for (const { title, to, expected } of windowEndCases) {
    test(`end date: ${title}`, async () => {
      const { service, eventsRepository } = makeService();

      await service.list({ to }, PAGE);

      assert.equal(eventsRepository.findPublished.mock.calls[0]?.arguments[0].to, expected);
    });
  }

  test('passes the category, venue and distance filters on unchanged', async () => {
    const { service, eventsRepository } = makeService();
    const query = {
      categoryIds: [aCategory().id],
      venueId: aVenue().id,
      near: { lat: 50.45, lng: 30.524, radiusKm: 3 },
    };

    await service.list(query, PAGE);

    assert.deepEqual(eventsRepository.findPublished.mock.calls[0]?.arguments[0], {
      ...query,
      from: TODAY,
      to: WINDOW_END,
    });
  });

  test('starts the window on the Kyiv date: at 00:30 in Kyiv, UTC is still on the day before', async () => {
    mock.timers.setTime(Date.parse('2026-10-14T21:30:00Z'));
    const { service, eventsRepository } = makeService();

    await service.list({}, PAGE);

    assert.equal(eventsRepository.findPublished.mock.calls[0]?.arguments[0].from, TODAY);
  });
});

// FR-009: О1 lists the organization's own events.
describe('EventsService.listOwn', () => {
  useFixedClock();

  test('asks for the caller’s events that end after now', async () => {
    const { service, eventsRepository } = makeService();

    await service.listOwn(ACCOUNT_ID, PAGE);

    assert.deepEqual(eventsRepository.findByOrganization.mock.calls[0]?.arguments, [ACCOUNT_ID, NOW, PAGE]);
  });
});

describe('EventsService.listByOrganization', () => {
  useFixedClock();

  test('lists the published events of a verified organization that have not ended', async () => {
    const { service, eventsRepository } = makeService();

    const page = await service.listByOrganization(ACCOUNT_ID, PAGE);

    assert.equal(page.items.length, 1);
    const [organizationId, endingAfter, request, status] = eventsRepository.findByOrganization.mock.calls[0]!.arguments;
    assert.deepEqual([organizationId, endingAfter, request, status], [ACCOUNT_ID, NOW, PAGE, 'published']);
  });

  test('answers NOT_FOUND for an organization that is not verified, or none', async () => {
    const { service, organizationsRepository, eventsRepository } = makeService();
    for (const organization of [anOrganization({ verificationStatus: 'pending' }), undefined]) {
      organizationsRepository.findByAccountId.mock.mockImplementation(() => Promise.resolve(organization));

      await assert.rejects(service.listByOrganization(ACCOUNT_ID, PAGE), isDomainError('NOT_FOUND'));
    }
    assert.equal(eventsRepository.findByOrganization.mock.callCount(), 0);
  });
});

describe('EventsService.getById', () => {
  test('returns the event without a cover', async () => {
    const { service } = makeService();

    assert.deepEqual(await service.getById(EVENT_ID), { ...anEvent(), photo: null, organizer: ORGANIZER });
  });

  test('returns the organizer with its logo', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findById.mock.mockImplementation(() =>
      Promise.resolve(anEvent({ organizer: { id: ACCOUNT_ID, name: 'Natalka Park', logoId: LOGO.id } })),
    );

    assert.deepEqual((await service.getById(EVENT_ID)).organizer, { ...ORGANIZER, logo: LOGO });
  });

  test('returns no organizer for an imported event', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findById.mock.mockImplementation(() =>
      Promise.resolve(anEvent({ source: 'import', organizationId: null, organizer: null })),
    );

    assert.equal((await service.getById(EVENT_ID)).organizer, null);
  });

  test('returns the event with its cover’s size and crop', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(anEvent({ photoId: PHOTO.id })));

    const event = await service.getById(EVENT_ID);

    assert.deepEqual(event.photo, PHOTO);
  });

  test('answers NOT_FOUND to an unknown event', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(undefined));

    await assert.rejects(service.getById(EVENT_ID), isDomainError('NOT_FOUND'));
  });
});

// FR-009
describe('EventsService.create', () => {
  test('publishes the event as the organization’s own', async () => {
    const { service, eventsRepository } = makeService();
    const input = aNewEvent();

    await service.create(ACCOUNT_ID, input);

    assert.deepEqual(eventsRepository.create.mock.calls[0]?.arguments, [
      { ...input, source: 'organization', status: 'published', organizationId: ACCOUNT_ID },
    ]);
  });

  test('rejects an organization that is not verified yet', async () => {
    const { service, eventsRepository, organizationsRepository } = makeService();
    organizationsRepository.findByAccountId.mock.mockImplementation(() =>
      Promise.resolve(anOrganization({ verificationStatus: 'pending' })),
    );

    await assert.rejects(service.create(ACCOUNT_ID, aNewEvent()), isDomainError('ORGANIZATION_NOT_VERIFIED'));
    assert.equal(eventsRepository.create.mock.callCount(), 0);
  });

  test('rejects an account that is not an organization', async () => {
    const { service, organizationsRepository } = makeService();
    organizationsRepository.findByAccountId.mock.mockImplementation(() => Promise.resolve(undefined));

    await assert.rejects(service.create(ACCOUNT_ID, aNewEvent()), isDomainError('ORGANIZATION_NOT_VERIFIED'));
  });

  test('rejects a category that is not active', async () => {
    const { service, eventsRepository, categoriesService } = makeService();
    categoriesService.findActive.mock.mockImplementation(() => Promise.resolve(undefined));

    await assert.rejects(service.create(ACCOUNT_ID, aNewEvent()), isDomainError('REFERENCE_NOT_FOUND'));
    assert.equal(eventsRepository.create.mock.callCount(), 0);
  });

  test('rejects a venue of another organization', async () => {
    const { service, eventsRepository, venuesRepository } = makeService();
    venuesRepository.findById.mock.mockImplementation(() =>
      Promise.resolve(aVenue({ organizationId: OTHER_ACCOUNT_ID })),
    );

    await assert.rejects(service.create(ACCOUNT_ID, aNewEvent()), isDomainError('REFERENCE_NOT_FOUND'));
    assert.equal(eventsRepository.create.mock.callCount(), 0);
  });

  test('rejects an unknown venue', async () => {
    const { service, venuesRepository } = makeService();
    venuesRepository.findById.mock.mockImplementation(() => Promise.resolve(undefined));

    await assert.rejects(service.create(ACCOUNT_ID, aNewEvent()), isDomainError('REFERENCE_NOT_FOUND'));
  });

  const timeCases = [
    {
      title: 'rejects an event that ends before it starts',
      startsAt: '2026-10-22T19:00:00+03:00',
      endsAt: '2026-10-22T18:00:00+03:00',
    },
    {
      title: 'rejects an event that ends when it starts',
      startsAt: '2026-10-22T19:00:00+03:00',
      endsAt: '2026-10-22T19:00:00+03:00',
    },
    {
      title: 'rejects an event that ends when it starts, written with another offset',
      startsAt: '2026-10-22T19:00:00+03:00',
      endsAt: '2026-10-22T18:00:00+02:00',
    },
  ];

  test('compares instants: accepts an end that reads earlier but is 30 minutes later in another offset', async () => {
    const { service, eventsRepository } = makeService();
    const input = aNewEvent({ startsAt: '2026-10-22T19:00:00+03:00', endsAt: '2026-10-22T18:30:00+02:00' });

    await service.create(ACCOUNT_ID, input);

    assert.equal(eventsRepository.create.mock.callCount(), 1);
  });

  for (const { title, startsAt, endsAt } of timeCases) {
    test(title, async () => {
      const { service, eventsRepository } = makeService();

      const creating = service.create(ACCOUNT_ID, aNewEvent({ startsAt, endsAt }));

      await assert.rejects(creating, isDomainError('EVENT_ENDS_BEFORE_START'));
      assert.equal(eventsRepository.create.mock.callCount(), 0);
    });
  }
});

// FR-011
describe('EventsService.update', () => {
  test('saves every editable field of the organization’s event', async () => {
    const { service, eventsRepository } = makeService();
    const input = aNewEvent({ title: 'Film quiz night: autumn edition' });

    await service.update(ACCOUNT_ID, EVENT_ID, input);

    assert.deepEqual(eventsRepository.update.mock.calls[0]?.arguments, [EVENT_ID, input]);
  });

  describe('tells matching in the transaction of the change only when a coming session changes', () => {
    useFixedClock();

    const cases: { name: string; input: Partial<NewEvent>; tells: boolean }[] = [
      { name: 'another title', input: { title: 'Film quiz night: autumn edition' }, tells: false },
      { name: 'a later end', input: { endsAt: '2026-10-22T21:30:00+03:00' }, tells: false },
      {
        name: 'another time of day',
        input: { startsAt: '2026-10-22T20:00:00+03:00', endsAt: '2026-10-22T22:00:00+03:00' },
        tells: true,
      },
      {
        name: 'another day',
        input: { startsAt: '2026-10-23T19:00:00+03:00', endsAt: '2026-10-23T21:00:00+03:00' },
        tells: true,
      },
    ];
    for (const { name, input, tells } of cases) {
      test(`${name}: ${tells ? 'event.changed' : 'no job'}`, async () => {
        const { service, eventsRepository, jobs } = makeService();
        const edited = aNewEvent(input);

        await service.update(ACCOUNT_ID, EVENT_ID, edited);

        assert.deepEqual(
          eventsRepository.update.mock.calls[0]?.arguments,
          tells ? [EVENT_ID, edited, TX] : [EVENT_ID, edited],
        );
        assert.deepEqual(
          enqueued(jobs),
          tells ? [['event.changed', { eventId: EVENT_ID, change: 'rescheduled' }, TX]] : [],
        );
      });
    }
  });

  test('fails, so that the change is rolled back, when the job cannot be enqueued', async () => {
    const { service, jobs } = makeService();
    jobs.enqueue.mock.mockImplementation(() => Promise.reject(new Error('The job queue is not running')));

    await assert.rejects(service.cancel(ACCOUNT_ID, EVENT_ID), /The job queue is not running/);
  });

  test('tells another organization the event does not exist, before checking anything else', async () => {
    const { service, eventsRepository, organizationsRepository } = makeService();

    await assert.rejects(service.update(OTHER_ACCOUNT_ID, EVENT_ID, aNewEvent()), isDomainError('NOT_FOUND'));
    assert.equal(organizationsRepository.findByAccountId.mock.callCount(), 0);
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });

  test('rejects an organization that has lost its verification', async () => {
    const { service, eventsRepository, organizationsRepository } = makeService();
    organizationsRepository.findByAccountId.mock.mockImplementation(() =>
      Promise.resolve(anOrganization({ verificationStatus: 'revoked' })),
    );

    const updating = service.update(ACCOUNT_ID, EVENT_ID, aNewEvent());

    await assert.rejects(updating, isDomainError('ORGANIZATION_NOT_VERIFIED'));
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });

  test('rejects editing a cancelled event', async () => {
    const { service, eventsRepository } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(anEvent({ status: 'cancelled' })));

    await assert.rejects(service.update(ACCOUNT_ID, EVENT_ID, aNewEvent()), isDomainError('EVENT_CANCELLED'));
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });

  test('rejects new times where the event ends before it starts', async () => {
    const { service, eventsRepository } = makeService();
    const input = aNewEvent({ startsAt: '2026-10-22T19:00:00+03:00', endsAt: '2026-10-22T18:00:00+03:00' });

    await assert.rejects(service.update(ACCOUNT_ID, EVENT_ID, input), isDomainError('EVENT_ENDS_BEFORE_START'));
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });
});

// FR-011
describe('EventsService.cancel', () => {
  test('saves the event as cancelled for the organization that posted it, and tells matching', async () => {
    const { service, eventsRepository, jobs } = makeService();

    const result = await service.cancel(ACCOUNT_ID, EVENT_ID);

    assert.equal(eventsRepository.update.mock.callCount(), 1);
    assert.deepEqual(eventsRepository.update.mock.calls[0]?.arguments, [EVENT_ID, { status: 'cancelled' }, TX]);
    assert.equal(result.status, 'cancelled');
    assert.deepEqual(enqueued(jobs), [['event.changed', { eventId: EVENT_ID, change: 'cancelled' }, TX]]);
  });

  test('tells another organization the event does not exist', async () => {
    const { service, eventsRepository } = makeService();

    const cancelling = service.cancel(OTHER_ACCOUNT_ID, EVENT_ID);

    await assert.rejects(cancelling, isDomainError('NOT_FOUND'));
    assert.equal(eventsRepository.update.mock.callCount(), 0);
  });

  test('returns an already cancelled event unchanged without saving anything', async () => {
    const { service, eventsRepository, jobs } = makeService();
    const cancelled = anEvent({ status: 'cancelled' });
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(cancelled));

    const result = await service.cancel(ACCOUNT_ID, EVENT_ID);

    assert.deepEqual(result, { ...cancelled, photo: null, organizer: ORGANIZER });
    assert.equal(eventsRepository.update.mock.callCount(), 0);
    assert.deepEqual(enqueued(jobs), []);
  });
});

// FR-009: an organization's event cover.
describe('EventsService.setPhoto', () => {
  test('cuts the upload as an event photo, points the event at it and deletes the old cover in one transaction', async () => {
    const { service, eventsRepository, imagesService, tx } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(anEvent({ photoId: OLD_PHOTO.id })));

    const event = await service.setPhoto(ACCOUNT_ID, EVENT_ID, UPLOAD);

    assert.deepEqual(imagesService.prepare.mock.calls[0]?.arguments, ['eventPhoto', UPLOAD]);
    assert.deepEqual(eventsRepository.setPhoto.mock.calls[0]?.arguments, [EVENT_ID, PHOTO.id, tx]);
    assert.deepEqual(imagesService.remove.mock.calls[0]?.arguments, [[OLD_PHOTO.id], tx]);
    assert.deepEqual(event.photo, PHOTO);
  });

  test('tells another organization the event does not exist, without reading the picture', async () => {
    const { service, imagesService } = makeService();

    await assert.rejects(service.setPhoto(OTHER_ACCOUNT_ID, EVENT_ID, UPLOAD), isDomainError('NOT_FOUND'));
    assert.equal(imagesService.prepare.mock.callCount(), 0);
  });

  test('keeps the cover of a cancelled event', async () => {
    const { service, eventsRepository, imagesService } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(anEvent({ status: 'cancelled' })));

    await assert.rejects(service.setPhoto(ACCOUNT_ID, EVENT_ID, UPLOAD), isDomainError('EVENT_CANCELLED'));
    assert.equal(imagesService.prepare.mock.callCount(), 0);
  });

  test('rejects an organization that is no longer verified', async () => {
    const { service, organizationsRepository, imagesService } = makeService();
    organizationsRepository.findByAccountId.mock.mockImplementation(() =>
      Promise.resolve(anOrganization({ verificationStatus: 'revoked' })),
    );

    await assert.rejects(service.setPhoto(ACCOUNT_ID, EVENT_ID, UPLOAD), isDomainError('ORGANIZATION_NOT_VERIFIED'));
    assert.equal(imagesService.prepare.mock.callCount(), 0);
  });
});

describe('EventsService.removePhoto', () => {
  test('clears the cover and deletes its picture', async () => {
    const { service, eventsRepository, imagesService, tx } = makeService();
    eventsRepository.findById.mock.mockImplementation(() => Promise.resolve(anEvent({ photoId: OLD_PHOTO.id })));

    const event = await service.removePhoto(ACCOUNT_ID, EVENT_ID);

    assert.deepEqual(eventsRepository.setPhoto.mock.calls[0]?.arguments, [EVENT_ID, null, tx]);
    assert.deepEqual(imagesService.remove.mock.calls[0]?.arguments, [[OLD_PHOTO.id], tx]);
    assert.equal(event.photo, null);
  });

  test('changes nothing for an event without a cover', async () => {
    const { service, eventsRepository, imagesService } = makeService();

    await service.removePhoto(ACCOUNT_ID, EVENT_ID);

    assert.equal(eventsRepository.setPhoto.mock.callCount(), 0);
    assert.equal(imagesService.remove.mock.callCount(), 0);
  });
});
